fe-area-inset-bottom));display:flex;align-items:center;justify-content:space-between;gap:20px;background:linear-gradient(0deg,rgba(5,10,16,.98),rgba(8,15,23,.93));border-top:1px solid rgba(115,207,230,.17);box-shadow:0 -8px 32px rgba(0,0,0,.24)}.build-tools,.bottom-right{display:flex;align-items:center;gap:10px}.tool-button{height:58px;min-width:179px;padding:0 12px;border:1px solid rgba(107,159,177,.22);border-radius:4px;background:linear-gradient(135deg,rgba(18,34,46,.93),rgba(11,21,30,.97));display:flex;align-items:center;text-align:left;gap:10px;color:#e9f8fb;cursor:pointer;position:relative;transition:.18s;touch-action:manipulation}.tool-button:hover,.tool-button.selected{border-color:rgba(91,230,255,.78);background:linear-gradient(135deg,rgba(24,56,70,.96),rgba(12,29,39,.98));box-shadow:inset 0 0 18px rgba(91,230,255,.07),0 0 16px rgba(91,230,255,.1)}.tool-button.selected:after{content:'PLACE';position:absolute;right:8px;top:-7px;background:#4adcf5;color:#061118;font:700 7px 'DM Mono',monospace;padding:2px 5px;letter-spacing:.7px}.tool-icon{width:33px;height:33px;display:grid;place-items:center;color:#66def4;position:relative;flex:0 0 33px}.pylon-icon:before{content:'';position:absolute;width:19px;height:19px;border:1px solid #61dff2;transform:rotate(45deg);box-shadow:0 0 10px rgba(88,228,255,.35)}.pylon-icon:after{content:'';position:absolute;width:27px;height:27px;border:1px solid rgba(97,223,242,.3);border-radius:50%}.pylon-icon i{width:5px;height:5px;border-radius:50%;background:#a7f8ff;box-shadow:0 0 9px #7ceeff;z-index:1}.turret-icon:before{content:'';position:absolute;width:17px;height:17px;border:1px solid #79ddff;border-radius:50%;box-shadow:0 0 8px rgba(90,219,255,.3)}.turret-icon:after{content:'';position:absolute;width:17px;height:5px;border:1px solid #79ddff;background:#183847;top:5px;left:14px;transform:rotate(-25deg);border-radius:4px}.turret-icon i{position:absolute;width:5px;height:5px;background:#9af7ff;border-radius:50%;box-shadow:0 0 8px #4