ranslate(-50%,-8px);padding:10px 16px;border:1px solid rgba(97,221,239,.25);background:rgba(7,18,26,.92);font:500 10px 'DM Mono',monospace;letter-spacing:.7px;color:#bceef5;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.rotate-tip{display:none}
